SELECT ?s ?class ?ts WHERE {
  ?s a brick:PerimeterTopZone .
  ?label ?s .
  FILTER(str(?label) = "Perimeter_top_ZN_4")
  OPTIONAL { ?s ref:hasTimeseriesId ?ts }
  OPTIONAL { ?s a ?class }
}

SELECT ?p ?class ?ts WHERE {
  ?p a brick:OccupancySensor .
  ?p brick:hasLocation ?loc .
  ?loc rdfs:label ?lbl .
  FILTER(CONTAINS(str(?lbl), "ZN_4"))
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p (STR(?s) AS ?sname) ?ts WHERE {
  ?p a brick:OccupancySensor .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p (STR(?p) AS ?pname) ?ts WHERE {
  ?p brick:hasLocation brick:Zone_F4_Z05 .
  ?p a ?cls .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  FILTER(str(?cls) != "")
}

